sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float r;
uniform float g;
uniform float b;
uniform float a;
float pick(float k, float4 c) {
    if (k < 0.5) return c.r;
    if (k < 1.5) return c.g;
    if (k < 2.5) return c.b;
    if (k < 3.5) return c.a;
    if (k < 4.5) return dot(c.rgb, float3(0.2126, 0.7152, 0.0722));
    if (k < 5.5) return 0.0;
    return 1.0;
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    float4 c = float4(src);
    if (c.a > 0.0) c.rgb /= c.a;
    float4 o = clamp(float4(pick(r, c), pick(g, c), pick(b, c), pick(a, c)), 0.0, 1.0);
    return half4(half3(o.rgb) * half(o.a), half(o.a));
}
